namespace Ordering;

/// <summary>Handles product returns, the refunds they trigger and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnProcessingRegistry _processedReturns = new();
    private readonly ReturnRestockLedger _restockLedger = new();
    private readonly ReturnRefundJournal _refundJournal = new();
    private readonly ReturnRefundCalculator _refundCalculator = new();

    public string ProcessReturn(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_processedReturns.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        if (!_restockLedger.RecordReturnedLines(order.Lines))
            return "quantity too high";
        if (!_restockLedger.HasTrackedSkus)
            return "no returnable lines";

        _processedReturns.Add(order.Reference);
        return "accepted";
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_processedReturns.Contains(order.Reference))
            return false;

        return ReturnEligibilityPolicy.HasReturnableLine(order.Lines);
    }

    public decimal ComputeRefund(Order order)
    {
        return _refundCalculator.Compute(order.Lines, _refundJournal.Count);
    }

    public void LogRefund(Order order, decimal amount)
    {
        _refundJournal.Log(order.Reference, amount);
    }

    public int Restock(Order order)
    {
        return _restockLedger.Restock(order.Lines);
    }
}

internal sealed class ReturnProcessingRegistry
{
    private readonly HashSet<string> _processedRefs = new(StringComparer.Ordinal);

    public bool Contains(string reference)
    {
        return _processedRefs.Contains(reference);
    }

    public void Add(string reference)
    {
        _processedRefs.Add(reference);
    }
}

internal static class ReturnEligibilityPolicy
{
    public static bool HasReturnableLine(IEnumerable<OrderLine> lines)
    {
        int valid = 0;
        foreach (var line in lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (string.IsNullOrEmpty(line.Sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (line.Quantity >= 1 && line.Quantity <= 100)
                valid++;
        }

        return valid > 0;
    }
}

internal sealed class ReturnRefundCalculator
{
    private const decimal UnitRefund = 5m;

    public decimal Compute(IEnumerable<OrderLine> lines, int refundLogCount)
    {
        decimal refund = 0m;
        foreach (var line in lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 50)
                refund += line.Quantity * UnitRefund * 0.9m;
            else if (line.Quantity > 10)
                refund += line.Quantity * UnitRefund * 0.95m;
            else if (line.Quantity > 1)
                refund += line.Quantity * UnitRefund;
            else
                refund += UnitRefund;
        }

        if (refundLogCount > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;
        return refund < 0m ? 0m : refund;
    }
}

internal sealed class ReturnRefundJournal
{
    private readonly List<string> _refundLog = new();

    public int Count => _refundLog.Count;

    public void Log(string reference, decimal amount)
    {
        if (amount <= 0m)
            return;
        if (string.IsNullOrEmpty(reference))
            return;
        if (_refundLog.Count == 0 || amount > 100m)
            _refundLog.Add($"{reference}:{amount}");
        else if (amount > 50m)
            _refundLog.Add($"{reference}:large:{amount}");
        else if (amount > 10m)
            _refundLog.Add($"{reference}:mid:{amount}");
        else
            _refundLog.Add($"{reference}:small:{amount}");
        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{reference}:flag");
    }
}

internal sealed class ReturnRestockLedger
{
    private readonly Dictionary<string, int> _restockBySku = new(StringComparer.Ordinal);

    public bool HasTrackedSkus => _restockBySku.Count != 0;

    public bool RecordReturnedLines(IEnumerable<OrderLine> lines)
    {
        foreach (var line in lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return false;
            _restockBySku[line.Sku] = _restockBySku.TryGetValue(line.Sku, out var count)
                ? count + line.Quantity
                : line.Quantity;
        }

        return true;
    }

    public int Restock(IEnumerable<OrderLine> lines)
    {
        int moved = 0;
        foreach (var line in lines)
        {
            if (line.Quantity <= 0)
                continue;
            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (_restockBySku.TryGetValue(sku, out var pending) && pending > 0)
            {
                moved += pending;
                _restockBySku[sku] = 0;
            }
            else if (line.Quantity > 50)
            {
                _restockBySku[sku] = line.Quantity / 2;
            }
            else if (line.Quantity > 0)
            {
                _restockBySku[sku] = line.Quantity;
            }
            if (moved > 100000)
                break;
        }

        return moved;
    }
}
